    async function history(record,version){const result=await request('recordVersions',{...scope(),recordId:record.id});if(!result)return;const box=heading('היסטוריה והשוואת גרסאות',true),choices=Object.fromEntries((result.versions||[]).map(v=>[v.id,'גרסה '+v.number+' · '+actorLabel(v.proposedBy)+' · '+dateLabel(v.createdAt)]));D.table(box,result.versions||[],[{key:'number',label:'גרסה'},{label:'הוצעה על ידי',render:v=>actorLabel(v.proposedBy)},{label:'נשמרה בתאריך',render:v=>dateLabel(v.createdAt)},{key:'contentHash',label:'טביעת הגרסה'}]);const before=D.field(box,'גרסה קודמת','select',result.versions?.[0]?.id||'',{choices}),after=D.field(box,'גרסה להשוואה','select',version.id,{choices}),ai=D.field(box,'צירוף הסבר השלכות בעזרת AI, אם השירות מוגדר','checkbox',false),changes=D.node('div');box.append(D.button('השוואת הגרסאות',async()=>{const impact=await request('workspaceImpact',{...scope(),recordId:record.id,fromVersionId:before.value,toVersionId:after.value,includeAI:ai.checked});if(impact){changes.replaceChildren();D.table(changes,impact.changes||[],[{key:'label',label:'שדה'},{label:'תחום',render:r=>CATEGORY_LABELS[r.category]||r.category},{key:'before',label:'לפני'},{key:'after',label:'אחרי'}]);D.paragraph(changes,impact.approvalsInvalidated?(record.kind==='agreement'?'שינוי בגרסה מזמין אישור חדש של שני הצדדים.':'הגרסה הקודמת נשמרת בהיסטוריה. הגשה מתוקנת נבדקת מחדש.'):'לא זוהה שינוי שמבטל את האישורים.');if(ai.checked)D.paragraph(changes,impact.ai?.summary||(impact.ai?.configured?'הסבר ההשלכות לא הופק.':'שירות הסבר ההשלכות טרם הוגדר.'));}}),D.button('חזרה לגרסה',()=>editRecord(records.get(record.id)||{record,version}),'r-secondary'),changes);}
    function exports(parent,record,version,access){if(access&&!access.canDownload){D.paragraph(parent,'ההרשאה שניתנה לגרסה זו מאפשרת צפייה. הורדה זמינה לאחר הקצאה נפרדת.','r-muted');return;}for(const[format,label]of [['docx','הורדת Word'],['html','PDF והדפסה']])parent.append(D.button(label,async()=>{if(!await leaveEditor(()=>true))return;const targetVersion=editor?.record?.id===record.id?editor.version:version;const data=await request('workspaceExport',{...scope(),recordId:record.id,versionId:targetVersion.id,format});if(!data)return;if(format==='docx'){downloadBytes(data);return;}const product=options.productDoc||(typeof window!=='undefined'?window.SBE_DOC:null);if(!product){notice('אפשר לפתוח את רכיב ההדפסה לאחר טעינה מחדש.',true);return;}const parsed=new DOMParser().parseFromString(decodeText(data.contentBase64),'text/html'),printable=D.node('div');for(const n of Array.from(parsed.body.children))printable.append(document.importNode(n,true));product.print({title:targetVersion.data.title||P.RECORD_KINDS[record.kind],subtitle:'גרסה '+targetVersion.number,node:printable,inline:true});},'r-secondary'));}
    function decodeText(base64){return new TextDecoder().decode(Uint8Array.from(atob(base64),c=>c.charCodeAt(0)));}
    function downloadBytes(data){if(options.download){options.download(data);return;}const bytes=Uint8Array.from(atob(data.contentBase64),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:data.mediaType})),a=D.node('a');a.href=url;a.download=data.filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),0);}
    function documentArea(parent,recordId,onUpload){const box=D.card(parent,recordId?'מסמכים פרטיים לרשומה':'מסמכים פרטיים ונספחים'),input=D.field(box,'צירוף מסמך פרטי','file');input.accept='.pdf,.docx,.txt,.png,.jpg,.jpeg,.webp';input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;if(file.size>8*1024*1024){notice('אפשר לצרף מסמך או תמונה עד 8 MB.',true);return;}const at=epoch;const bytes=new Uint8Array(await file.arrayBuffer());if(at!==epoch)return;let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);const result=await request('workspaceDocumentPut',{...scope(),...(recordId?{recordId}:{}),filename:file.name,mediaType:file.type||({pdf:'application/pdf',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',txt:'text/plain',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp'})[file.name.split('.').pop().toLowerCase()]||'application/octet-stream',contentBase64:btoa(binary)});if(result){documents.push(result.document);input.value='';renderDocs();onUpload?.(result.document);notice('המסמך נשמר בתיק הפרטי.');}});D.paragraph(box,'המסמכים נשמרים בתיק לפי הרשאות המחקר. הורדה נבדקת בנפרד בכל פתיחה.','r-muted');const listing=D.node('div');box.append(listing);function renderDocs(){listing.replaceChildren();for(const doc of documents.filter(d=>!recordId||d.recordId===recordId)){const row=D.node('div','r-toolbar');row.append(D.node('span','',doc.filename),D.button('הורדת מסמך',async()=>{const result=await request('workspaceDocumentGet',{...scope(),documentId:doc.id,download:true});if(result)downloadBytes({filename:result.document.filename,mediaType:result.document.mediaType,contentBase64:result.contentBase64});},'r-secondary'));listing.append(row);}}renderDocs();}
    async function contributionReport(){if(!bootstrap.owner)return;const result=await request('workspaceList',{studyId:workspace.studyId});if(!result)return;const report=[];for(const w of result.workspaces||[])for(const summary of w.records||[])if(['contribution','obligation','agreement'].includes(summary.kind)){const data=await request('recordGet',{studyId:w.studyId,partnerId:w.partnerId,recordId:summary.id});if(data)report.push({...data,workspace:w});}const box=heading('דוח תרומות לפי מחקר',true),printable=D.node('div');box.append(printable);D.paragraph(printable,workspace.studyTitle||'');D.paragraph(printable,'התנאים המבוקשים נשמרים בהצעה המקורית. תנאים מוצעים שאושרו נרשמים בנפרד ואינם יוצרים התחייבות כספית ללא הסכם חתום.');const contributions=report.filter(d=>d.record.kind==='contribution'),obligations=report.filter(d=>d.record.kind==='obligation'),agreements=report.filter(d=>d.record.kind==='agreement');D.table(printable,Object.entries(P.RECORD_STATUSES.contribution).map(([status,label])=>({label,count:contributions.filter(d=>d.record.status===status).length})),[{key:'label',label:'מצב התרומה'},{key:'count',label:'מספר תרומות'}]);D.table(printable,Object.entries(P.CONTRIBUTION_CATEGORIES).map(([category,label])=>({label,count:contributions.filter(d=>d.version.data.category===category).length})),[{key:'label',label:'סוג התרומה'},{key:'count',label:'מספר תרומות'}]);
      function total(items,field,currency){let cents=0n;for(const item of items){const amount=item.version.data[field];if(item.version.data.currency===currency&&/^\d+\.\d{2}$/.test(amount||''))cents+=BigInt(amount.replace('.',''));}return (cents/100n).toString()+'.'+(cents%100n).toString().padStart(2,'0');}
      D.table(printable,['ILS','USD','EUR','GBP'].map(currency=>({currency,proposed:total(contributions,'requestedCompensation',currency),signed:total(obligations.filter(d=>d.record.binding===true),'amount',currency)})),[{key:'currency',label:'מטבע'},{key:'proposed',label:'תמורה שהתבקשה בהצעות'},{key:'signed',label:'סכום מתוך התחייבויות חתומות ומאומתות'}]);
      for(const data of contributions){const section=D.card(printable,(data.workspace.partnerName||'חוקרת')+' · '+(data.version.data.title||'תרומה'));renderData(section,'contribution',data.version.data);D.paragraph(section,P.RECORD_STATUSES.contribution[data.record.status]);for(const review of data.reviews||[])if(review.approvedTerms){const terms=D.card(section,'תנאים מוצעים שאושרו בנפרד');for(const def of P.APPROVED_TERMS_FIELDS)if(review.approvedTerms[def.id]!==undefined)D.paragraph(terms,def.label+': '+readable(def,review.approvedTerms[def.id]));}for(const agreement of agreements)if((agreement.version.data.contributionIds||[]).includes(data.record.id))section.append(D.button('נספח ד׳ בהסכם: '+agreement.version.data.title,()=>openWorkspace(agreement.workspace,{editor:{kind:'agreement',recordId:agreement.record.id,revision:agreement.record.revision,data:agreement.version.data}}),'r-secondary'));}
      const rights=D.card(printable,'זכויות, רישיונות וייחוס בהסכמים');for(const data of agreements){D.paragraph(rights,(data.workspace.partnerName||'')+' · '+data.version.data.title+' · '+(data.record.status==='executed'?'הסכם שנחתם ואומת':'נוסח מוצע'));for(const def of P.RECORD_SCHEMAS.agreement.fields.filter(f=>f.section==='mutualIP'&&f.type!=='id'))if(data.version.data[def.id])D.paragraph(rights,def.label+': '+readable(def,data.version.data[def.id]));}
      const outstanding=D.card(printable,'התחייבויות למעקב מתוך הסכמים חתומים');for(const data of obligations.filter(d=>d.record.binding===true&&!['completed','cancelled'].includes(d.record.status))){D.paragraph(outstanding,(data.workspace.partnerName||'')+' · '+data.version.data.title+' · '+dateLabel(data.version.data.dueDate));renderData(outstanding,'obligation',data.version.data);}if(!outstanding.children.some(n=>n.className==='r-value'))D.paragraph(outstanding,'אין כרגע התחייבויות חתומות פתוחות למעקב.','r-muted');box.append(D.button('PDF והדפסת דוח התרומות',()=>{const product=options.productDoc||(typeof window!=='undefined'?window.SBE_DOC:null);if(product)product.print({title:'דוח תרומות · '+workspace.studyTitle,node:printable,inline:true});else notice('רכיב ההדפסה טרם נטען.',true);},'r-secondary'));
    }
    function invitationControls(parent){const fold=D.node('details','r-fold');fold.append(D.node('summary','','הזמנה אישית לשותפות'));const preset=D.field(fold,'מסלול גישה','select','approved_findings',{choices:{approved_findings:'ממצאים מאושרים',collaborative_analysis:'ניתוח משותף'}}),expiry=D.field(fold,'תוקף הזמנה מוקדם יותר, לפי בחירה','date');fold.append(D.button('יצירת הזמנה אישית',async()=>{const result=await request('partnerInviteCreate',{...scope(),preset:preset.value,...(expiry.value?{expiresAt:new Date(expiry.value+'T23:59:59').toISOString()}:{})});if(result){notice(result.delivery?.configured?'ההזמנה הוכנה. מצב המשלוח: '+(result.delivery.status||'לא ידוע'):'ההזמנה נשמרה. שירות הדוא״ל טרם הוגדר.');const invitation=result.invitation;if(invitation?.status==='pending')fold.append(D.button('ביטול ההזמנה',async()=>{const revoked=await request('partnerInviteRevoke',{...scope(),invitationId:invitation.id,expectedRevision:invitation.revision});if(revoked)notice('ההזמנה בוטלה.');},'r-danger'));}}));parent.append(fold);}
    async function invitation(invite){const result=await request('partnerInviteGet',{invite});if(!result)return;const box=heading('הזמנה לשותפות במחקר');D.paragraph(box,result.invitation.studyTitle||'');D.paragraph(box,'תוקף ההזמנה: '+dateLabel(result.invitation.expiresAt));D.paragraph(box,'פתיחת ההזמנה מאפשרת לעיין בפרטים. ההצטרפות נרשמת לאחר אישור.');box.append(D.button('אישור ההצטרפות למחקר',async()=>{const accepted=await request('partnerInviteAccept',{invite});if(accepted){options.invite='';options.onInviteAccepted?.();await load();}}));}
    function capture(){return {intake:intakePage?.capture(),workspace:workspace?{studyId:workspace.studyId,partnerId:workspace.partnerId}:null,editor:editor?{kind:editor.kind,recordId:editor.record?.id,revision:editor.record?.revision,data:editor.read(),dirty:editor.dirty,...bootstrap?.owner&&editor.policyRead?{policyDraft:editor.policyRead()}:{} }:null};}
    return Object.freeze({load,clear,capture,openWorkspace});
